public class OrderService {
    public void processOrder(Long orderId) {
        // 'orderId' is a local reference variable on the stack
        // It points to a Long object on the heap

        // 'order' reference lives on stack, Order object lives on heap
        Order order = new Order(orderId, "Laptop");

        // 'items' reference on stack, ArrayList object on heap
        var items = new ArrayList<String>();
        items.add("Keyboard");
        items.add("Mouse");

        // When method returns, stack frame is popped:
        // - orderId, order, items references disappear from stack
        // - Objects on heap remain until GC determines they're unreachable
    }
}

record Order(Long id, String product) {}
// All fields of this record live on the heap as part of the Order object
