public class CalculationService {

    public int calculateDiscount(int price, int discountPercent) {
        // Frame 1: calculateDiscount
        // Local variables: price, discountPercent, discountAmount
        // Operand stack: used for arithmetic operations below

        int discountAmount = computeAmount(price, discountPercent);
        return price - discountAmount;
        // Return address: back to caller of calculateDiscount
    }

    private int computeAmount(int price, int percent) {
        // Frame 2: computeAmount (pushed on top of Frame 1)
        // Local variables: price, percent
        // Operand stack: holds intermediate multiplication and division results

        return (price * percent) / 100;
        // When returning, Frame 2 is popped, execution resumes in Frame 1
    }
}
// Each method call creates a new stack frame
// Frames are popped in reverse order (LIFO)
