public class RecursionDemo {

    // PROBLEM: Infinite recursion - no base case
    public void infiniteRecursion(int n) {
        System.out.println("Call " + n);
        infiniteRecursion(n + 1);  // Keeps creating frames forever
        // Eventually throws StackOverflowError
    }

    // PROBLEM: Missing base case in legitimate recursion
    public int factorial(int n) {
        return n * factorial(n - 1);  // Never stops!
        // Should have: if (n <= 1) return 1;
    }

    // SOLUTION: Proper base case stops recursion
    public int factorialCorrect(int n) {
        if (n <= 1) return 1;  // Base case prevents infinite frames
        return n * factorialCorrect(n - 1);
    }

    // PROBLEM: Mutually recursive methods without termination
    public void methodA() {
        methodB();  // A calls B
    }

    public void methodB() {
        methodA();  // B calls A - infinite loop
    }
}
