public class PaymentService {
    // Instance variable: on heap, shared by all threads
    private int totalPayments = 0;  // NOT thread-safe!

    public void processPayment(int amount) {
        // Local variable: on stack, private to each thread
        int localAmount = amount;  // Automatically thread-safe

        // Local reference: on stack, but points to shared heap object
        var payment = new Payment(localAmount);

        // PROBLEM: Multiple threads increment shared heap variable
        totalPayments++;  // Race condition! Needs synchronization

        // Local variable modifications are safe
        localAmount += 10;  // No thread can interfere with this

        // Even in loops, local variables are thread-safe
        for (int i = 0; i < 5; i++) {  // 'i' is on stack, isolated
            System.out.println(i);
        }
    }
}

record Payment(int amount) {}
// This object lives on heap, could be shared, needs careful handling
