public class UserService {

    public User processUser(Long userId) {
        // Frame pushed: contains userId, user, age locals

        // 'user' reference is on stack, User object on heap
        User user = repository.findById(userId).orElseThrow();

        // 'age' primitive local variable on stack
        int age = user.getAge();

        // 'processed' reference on stack, ProcessedUser object on heap
        var processed = new ProcessedUser(user.getName(), age + 1);

        return processed;  // Return processed reference to caller

        // STACK: Frame is popped immediately
        //   - userId, user, age, processed references disappear from stack
        //   - Stack memory is instantly reclaimed, no GC needed

        // HEAP: Objects remain until GC decides they're unreachable
        //   - If caller stores processed, that heap object stays alive
        //   - If no references exist to User object, it becomes GC candidate
    }
}

record ProcessedUser(String name, int age) {}
