```java
public class StringPoolDemo {

    public void demonstrateStringPool() {
        // Literals are automatically interned in the String pool
        String s1 = "hello";  // Added to pool (or reused if exists)
        String s2 = "hello";  // Reuses same pooled object

        // s1 and s2 point to the SAME object on heap (in pool)
        System.out.println(s1 == s2);  // true (same reference)

        // new String() creates a NEW heap object outside the pool
        String s3 = new String("hello");  // New object, not pooled

        // s1 and s3 are different objects (one pooled, one not)
        System.out.println(s1 == s3);  // false (different references)
        System.out.println(s1.equals(s3));  // true (same content)

        // Manually intern() adds to pool or returns pooled instance
        String s4 = s3.intern();  // Returns pooled "hello" object
        System.out.println(s1 == s4);  // true (same pooled reference)

        // Concatenation creates new objects, not pooled by default
        String s5 = "hel" + "lo";  // Compile-time constant, pooled
        String s6 = "hel" + new String("lo");  // Runtime, new object
    }
}
